import{_ as o,a as s,c as n,ac as a}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第一册：英语初阶 · 全册短语与句型 · 第28–55课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第一册：英语初阶 · 全册短语与句型 · 第28–55课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-1/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册短语与句型 · 第1–27课","link":"/life/english/new-concept/book-1/phrases-part-01"},"next":{"text":"第一册：英语初阶 · 全册短语与句型 · 第56–83课","link":"/life/english/new-concept/book-1/phrases-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册短语与句型 · 第1–27课","link":"/life/english/new-concept/book-1/phrases-part-01"},"next":{"text":"第一册：英语初阶 · 全册短语与句型 · 第56–83课","link":"/life/english/new-concept/book-1/phrases-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-1/phrases-part-02.md","filePath":"life/english/new-concept/book-1/phrases-part-02.md"}'),l={name:"life/english/new-concept/book-1/phrases-part-02.md"};function i(t,e,r,h,p,c){return s(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="第一册-英语初阶-·-全册短语与句型-·-第28–55课" tabindex="-1">第一册：英语初阶 · 全册短语与句型 · 第28–55课 <a class="header-anchor" href="#第一册-英语初阶-·-全册短语与句型-·-第28–55课" aria-label="Permalink to &quot;第一册：英语初阶 · 全册短语与句型 · 第28–55课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="lesson-28-·-there-are-与复数位置" tabindex="-1">Lesson 28 · there are 与复数位置 <a class="header-anchor" href="#lesson-28-·-there-are-与复数位置" aria-label="Permalink to &quot;Lesson 28 · there are 与复数位置 {#lesson-28-·-there-are-与复数位置}&quot;">​</a></h2><ul><li>there are — 引出复数物品</li><li>next to — 紧挨着</li></ul><p><strong>句型示范：</strong> The pictures are between the windows.</p><p>The pictures 是复数主语，所以用 are；between the windows 把多个窗户作为位置参照。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-028">进入本课</a></p><h2 id="lesson-29-·-祈使句与-must" tabindex="-1">Lesson 29 · 祈使句与 must <a class="header-anchor" href="#lesson-29-·-祈使句与-must" aria-label="Permalink to &quot;Lesson 29 · 祈使句与 must {#lesson-29-·-祈使句与-must}&quot;">​</a></h2><ul><li>please sit down — 礼貌指令</li><li>must finish — 表示必须完成</li></ul><p><strong>句型示范：</strong> Please close the cupboard quietly.</p><p>Please close 是礼貌指令，the cupboard 是 close 的宾语；quietly 是副词，修饰关柜子的动作。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-029">进入本课</a></p><h2 id="lesson-30-·-祈使句与-must" tabindex="-1">Lesson 30 · 祈使句与 must <a class="header-anchor" href="#lesson-30-·-祈使句与-must" aria-label="Permalink to &quot;Lesson 30 · 祈使句与 must {#lesson-30-·-祈使句与-must}&quot;">​</a></h2><ul><li>please sit down — 礼貌指令</li><li>must finish — 表示必须完成</li></ul><p><strong>句型示范：</strong> I must tidy my desk before lunch.</p><p>I 是主语，must 后直接接 tidy；my desk 是宾语，before lunch 说明完成动作的时间界限。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-030">进入本课</a></p><h2 id="lesson-31-·-现在进行时单数" tabindex="-1">Lesson 31 · 现在进行时单数 <a class="header-anchor" href="#lesson-31-·-现在进行时单数" aria-label="Permalink to &quot;Lesson 31 · 现在进行时单数 {#lesson-31-·-现在进行时单数}&quot;">​</a></h2><ul><li>be reading — 正在阅读</li><li>at the moment — 此刻</li></ul><p><strong>句型示范：</strong> Nora is reading beside the window.</p><p>Nora 为单数主语，is reading 构成现在进行时；beside the window 只提供地点，不参与谓语变化。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-031">进入本课</a></p><h2 id="lesson-32-·-现在进行时单数" tabindex="-1">Lesson 32 · 现在进行时单数 <a class="header-anchor" href="#lesson-32-·-现在进行时单数" aria-label="Permalink to &quot;Lesson 32 · 现在进行时单数 {#lesson-32-·-现在进行时单数}&quot;">​</a></h2><ul><li>be reading — 正在阅读</li><li>at the moment — 此刻</li></ul><p><strong>句型示范：</strong> Is the cat sleeping under the chair?</p><p>Is 从 is sleeping 中前置形成问句；the cat 是主语，under the chair 说明睡觉的位置。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-032">进入本课</a></p><h2 id="lesson-33-·-现在进行时复数" tabindex="-1">Lesson 33 · 现在进行时复数 <a class="header-anchor" href="#lesson-33-·-现在进行时复数" aria-label="Permalink to &quot;Lesson 33 · 现在进行时复数 {#lesson-33-·-现在进行时复数}&quot;">​</a></h2><ul><li>be swimming — 正在游泳</li><li>walk along — 沿着走</li></ul><p><strong>句型示范：</strong> The children are drawing by the pond.</p><p>The children 是复数主语，are drawing 表示现在正在进行的动作；by the pond 表在池塘旁边。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-033">进入本课</a></p><h2 id="lesson-34-·-现在进行时复数" tabindex="-1">Lesson 34 · 现在进行时复数 <a class="header-anchor" href="#lesson-34-·-现在进行时复数" aria-label="Permalink to &quot;Lesson 34 · 现在进行时复数 {#lesson-34-·-现在进行时复数}&quot;">​</a></h2><ul><li>be swimming — 正在游泳</li><li>walk along — 沿着走</li></ul><p><strong>句型示范：</strong> Two dogs are running across the field.</p><p>Two dogs 是复数主语；run 双写 n 后加 ing，are running 构成进行时；across the field 表横穿田野。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-034">进入本课</a></p><h2 id="lesson-35-·-位置与方向介词" tabindex="-1">Lesson 35 · 位置与方向介词 <a class="header-anchor" href="#lesson-35-·-位置与方向介词" aria-label="Permalink to &quot;Lesson 35 · 位置与方向介词 {#lesson-35-·-位置与方向介词}&quot;">​</a></h2><ul><li>walk across — 步行横穿</li><li>go into — 进入内部</li></ul><p><strong>句型示范：</strong> A narrow bridge crosses the river.</p><p>A narrow bridge 是单数主语，crosses 是一般现在时第三人称形式；the river 是 crosses 的宾语。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-035">进入本课</a></p><h2 id="lesson-36-·-位置与方向介词" tabindex="-1">Lesson 36 · 位置与方向介词 <a class="header-anchor" href="#lesson-36-·-位置与方向介词" aria-label="Permalink to &quot;Lesson 36 · 位置与方向介词 {#lesson-36-·-位置与方向介词}&quot;">​</a></h2><ul><li>walk across — 步行横穿</li><li>go into — 进入内部</li></ul><p><strong>句型示范：</strong> The visitors are walking along the river.</p><p>The visitors 为复数主语，are walking 描述正在步行；along the river 说明沿河线性移动，而不是横渡河流。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-036">进入本课</a></p><h2 id="lesson-37-·-be-going-to-表计划" tabindex="-1">Lesson 37 · be going to 表计划 <a class="header-anchor" href="#lesson-37-·-be-going-to-表计划" aria-label="Permalink to &quot;Lesson 37 · be going to 表计划 {#lesson-37-·-be-going-to-表计划}&quot;">​</a></h2><ul><li>be going to make — 计划制作</li><li>paint it blue — 将其刷成蓝色</li></ul><p><strong>句型示范：</strong> We are going to paint the bench tomorrow.</p><p>We are going to paint 表计划，paint 用原形；the bench 为宾语，tomorrow 把计划放在明天。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-037">进入本课</a></p><h2 id="lesson-38-·-be-going-to-表计划" tabindex="-1">Lesson 38 · be going to 表计划 <a class="header-anchor" href="#lesson-38-·-be-going-to-表计划" aria-label="Permalink to &quot;Lesson 38 · be going to 表计划 {#lesson-38-·-be-going-to-表计划}&quot;">​</a></h2><ul><li>be going to make — 计划制作</li><li>paint it blue — 将其刷成蓝色</li></ul><p><strong>句型示范：</strong> I am measuring the shelf now.</p><p>I am measuring 是现在进行时，now 强调眼前动作；它与计划结构 going to measure 的时间视角不同。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-038">进入本课</a></p><h2 id="lesson-39-·-否定祈使句与宾语代词" tabindex="-1">Lesson 39 · 否定祈使句与宾语代词 <a class="header-anchor" href="#lesson-39-·-否定祈使句与宾语代词" aria-label="Permalink to &quot;Lesson 39 · 否定祈使句与宾语代词 {#lesson-39-·-否定祈使句与宾语代词}&quot;">​</a></h2><ul><li>do not drop — 提醒不要摔下</li><li>be careful — 提醒注意安全</li></ul><p><strong>句型示范：</strong> Do not put the wet box on the bed.</p><p>Do not 加 put 原形构成否定祈使句；the wet box 为对象，on the bed 为禁止放置的位置。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-039">进入本课</a></p><h2 id="lesson-40-·-否定祈使句与宾语代词" tabindex="-1">Lesson 40 · 否定祈使句与宾语代词 <a class="header-anchor" href="#lesson-40-·-否定祈使句与宾语代词" aria-label="Permalink to &quot;Lesson 40 · 否定祈使句与宾语代词 {#lesson-40-·-否定祈使句与宾语代词}&quot;">​</a></h2><ul><li>do not drop — 提醒不要摔下</li><li>be careful — 提醒注意安全</li></ul><p><strong>句型示范：</strong> We are going to carry it upstairs.</p><p>We are going to carry 表打算；it 指前文物品，作 carry 的宾语；upstairs 是方向副词，不加 to。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-040">进入本课</a></p><h2 id="lesson-41-·-不可数名词与量词" tabindex="-1">Lesson 41 · 不可数名词与量词 <a class="header-anchor" href="#lesson-41-·-不可数名词与量词" aria-label="Permalink to &quot;Lesson 41 · 不可数名词与量词 {#lesson-41-·-不可数名词与量词}&quot;">​</a></h2><ul><li>a bottle of — 一瓶；数量落在 bottle</li><li>some water — 一些水</li></ul><p><strong>句型示范：</strong> There is a bottle of juice in my bag.</p><p>There is 的单数依据是数量核心 a bottle；of juice 说明瓶中内容，in my bag 是地点。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-041">进入本课</a></p><h2 id="lesson-42-·-不可数名词与量词" tabindex="-1">Lesson 42 · 不可数名词与量词 <a class="header-anchor" href="#lesson-42-·-不可数名词与量词" aria-label="Permalink to &quot;Lesson 42 · 不可数名词与量词 {#lesson-42-·-不可数名词与量词}&quot;">​</a></h2><ul><li>a bottle of — 一瓶；数量落在 bottle</li><li>some water — 一些水</li></ul><p><strong>句型示范：</strong> Is there any paper in the drawer?</p><p>Is there 询问存在，paper 为物质义不可数名词，any 表不确定数量；in the drawer 说明搜索范围。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-042">进入本课</a></p><h2 id="lesson-43-·-some-any-与存在句疑问" tabindex="-1">Lesson 43 · some/any 与存在句疑问 <a class="header-anchor" href="#lesson-43-·-some-any-与存在句疑问" aria-label="Permalink to &quot;Lesson 43 · some/any 与存在句疑问 {#lesson-43-·-some-any-与存在句疑问}&quot;">​</a></h2><ul><li>is there any — 询问不可数物品</li><li>are there any — 询问复数物品</li></ul><p><strong>句型示范：</strong> Are there any clean mugs in the cupboard?</p><p>Mugs 为复数，所以用 Are there；any 在中性疑问中表示有没有一些，clean 修饰 mugs。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-043">进入本课</a></p><h2 id="lesson-44-·-some-any-与存在句疑问" tabindex="-1">Lesson 44 · some/any 与存在句疑问 <a class="header-anchor" href="#lesson-44-·-some-any-与存在句疑问" aria-label="Permalink to &quot;Lesson 44 · some/any 与存在句疑问 {#lesson-44-·-some-any-与存在句疑问}&quot;">​</a></h2><ul><li>is there any — 询问不可数物品</li><li>are there any — 询问复数物品</li></ul><p><strong>句型示范：</strong> There is not any milk in the fridge.</p><p>Milk 为不可数名词，所以用 is；not any 表数量为零。in the fridge 限定不存在牛奶的位置。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-044">进入本课</a></p><h2 id="lesson-45-·-can-表能力" tabindex="-1">Lesson 45 · can 表能力 <a class="header-anchor" href="#lesson-45-·-can-表能力" aria-label="Permalink to &quot;Lesson 45 · can 表能力 {#lesson-45-·-can-表能力}&quot;">​</a></h2><ul><li>can type — 能够打字</li><li>in a minute — 一会儿；一分钟后</li></ul><p><strong>句型示范：</strong> My colleague can translate this message.</p><p>My colleague 是第三人称单数，但 can 不加 s；translate 用原形，this message 为宾语。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-045">进入本课</a></p><h2 id="lesson-46-·-can-表能力" tabindex="-1">Lesson 46 · can 表能力 <a class="header-anchor" href="#lesson-46-·-can-表能力" aria-label="Permalink to &quot;Lesson 46 · can 表能力 {#lesson-46-·-can-表能力}&quot;">​</a></h2><ul><li>can type — 能够打字</li><li>in a minute — 一会儿；一分钟后</li></ul><p><strong>句型示范：</strong> Can you print the report today?</p><p>Can 前置形成问句，you 为主语，print 为原形；today 说明希望完成任务的时间。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-046">进入本课</a></p><h2 id="lesson-47-·-实义动词的一般现在时问句" tabindex="-1">Lesson 47 · 实义动词的一般现在时问句 <a class="header-anchor" href="#lesson-47-·-实义动词的一般现在时问句" aria-label="Permalink to &quot;Lesson 47 · 实义动词的一般现在时问句 {#lesson-47-·-实义动词的一般现在时问句}&quot;">​</a></h2><ul><li>do you like — 问通常喜好</li><li>want some tea — 想喝些茶</li></ul><p><strong>句型示范：</strong> Do you like coffee without sugar?</p><p>Do 帮助 like 形成一般疑问句；coffee 是宾语，without sugar 修饰所说的咖啡，表示不加糖。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-047">进入本课</a></p><h2 id="lesson-48-·-实义动词的一般现在时问句" tabindex="-1">Lesson 48 · 实义动词的一般现在时问句 <a class="header-anchor" href="#lesson-48-·-实义动词的一般现在时问句" aria-label="Permalink to &quot;Lesson 48 · 实义动词的一般现在时问句 {#lesson-48-·-实义动词的一般现在时问句}&quot;">​</a></h2><ul><li>do you like — 问通常喜好</li><li>want some tea — 想喝些茶</li></ul><p><strong>句型示范：</strong> I do not want a cold drink now.</p><p>I do not want 是一般现在时否定；want 保持原形，a cold drink 为宾语，now 说明当前需求。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-048">进入本课</a></p><h2 id="lesson-49-·-第三人称单数与-does" tabindex="-1">Lesson 49 · 第三人称单数与 does <a class="header-anchor" href="#lesson-49-·-第三人称单数与-does" aria-label="Permalink to &quot;Lesson 49 · 第三人称单数与 does {#lesson-49-·-第三人称单数与-does}&quot;">​</a></h2><ul><li>does not like — 助动词后恢复原形</li><li>at the butcher&#39;s — 在肉店，省略 shop</li></ul><p><strong>句型示范：</strong> My brother prefers fish to beef.</p><p>My brother 是单数主语，prefer 加 s；prefer A to B 表示在两者之间偏爱 A，to 不是不定式标记。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-049">进入本课</a></p><h2 id="lesson-50-·-第三人称单数与-does" tabindex="-1">Lesson 50 · 第三人称单数与 does <a class="header-anchor" href="#lesson-50-·-第三人称单数与-does" aria-label="Permalink to &quot;Lesson 50 · 第三人称单数与 does {#lesson-50-·-第三人称单数与-does}&quot;">​</a></h2><ul><li>does not like — 助动词后恢复原形</li><li>at the butcher&#39;s — 在肉店，省略 shop</li></ul><p><strong>句型示范：</strong> Does your daughter eat carrots?</p><p>Does 标记第三人称疑问，your daughter 为主语，eat 恢复原形；carrots 作泛指食物，不加冠词。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-050">进入本课</a></p><h2 id="lesson-51-·-come-from-与国籍表达" tabindex="-1">Lesson 51 · come from 与国籍表达 <a class="header-anchor" href="#lesson-51-·-come-from-与国籍表达" aria-label="Permalink to &quot;Lesson 51 · come from 与国籍表达 {#lesson-51-·-come-from-与国籍表达}&quot;">​</a></h2><ul><li>come from — 表示来源</li><li>in spring — 在春季</li></ul><p><strong>句型示范：</strong> My neighbours come from Portugal.</p><p>My neighbours 是复数主语，come 不加 s；from Portugal 是来源信息，不能把 come 换成 are come。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-051">进入本课</a></p><h2 id="lesson-52-·-come-from-与国籍表达" tabindex="-1">Lesson 52 · come from 与国籍表达 <a class="header-anchor" href="#lesson-52-·-come-from-与国籍表达" aria-label="Permalink to &quot;Lesson 52 · come from 与国籍表达 {#lesson-52-·-come-from-与国籍表达}&quot;">​</a></h2><ul><li>come from — 表示来源</li><li>in spring — 在春季</li></ul><p><strong>句型示范：</strong> It is often windy here in spring.</p><p>It 是天气主语；is 后放频率副词 often，windy 为表语。in spring 说明季节，不用 on。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-052">进入本课</a></p><h2 id="lesson-53-·-频率副词与天气动词" tabindex="-1">Lesson 53 · 频率副词与天气动词 <a class="header-anchor" href="#lesson-53-·-频率副词与天气动词" aria-label="Permalink to &quot;Lesson 53 · 频率副词与天气动词 {#lesson-53-·-频率副词与天气动词}&quot;">​</a></h2><ul><li>it often rains — 常见天气规律</li><li>be usually warm — 频率副词放 be 后</li></ul><p><strong>句型示范：</strong> It often rains in this coastal town.</p><p>It 是天气主语，rains 是实义动词第三人称形式；often 在实义动词之前，in this coastal town 是地点。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-053">进入本课</a></p><h2 id="lesson-54-·-频率副词与天气动词" tabindex="-1">Lesson 54 · 频率副词与天气动词 <a class="header-anchor" href="#lesson-54-·-频率副词与天气动词" aria-label="Permalink to &quot;Lesson 54 · 频率副词与天气动词 {#lesson-54-·-频率副词与天气动词}&quot;">​</a></h2><ul><li>it often rains — 常见天气规律</li><li>be usually warm — 频率副词放 be 后</li></ul><p><strong>句型示范：</strong> The evenings are usually cool in autumn.</p><p>The evenings 是复数主语，are 后放 usually，cool 作表语；in autumn 表季节。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-054">进入本课</a></p><h2 id="lesson-55-·-一般现在时的习惯动作" tabindex="-1">Lesson 55 · 一般现在时的习惯动作 <a class="header-anchor" href="#lesson-55-·-一般现在时的习惯动作" aria-label="Permalink to &quot;Lesson 55 · 一般现在时的习惯动作 {#lesson-55-·-一般现在时的习惯动作}&quot;">​</a></h2><ul><li>every morning — 每天早晨</li><li>arrive home — 到家，home 前不加 at</li></ul><p><strong>句型示范：</strong> My father leaves home at half past seven.</p><p>My father 为第三人称单数，所以用 leaves；home 在 leave home 中表示离开家，at half past seven 表钟点。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-055">进入本课</a></p>',143)])])}const d=o(l,[["render",i]]);export{g as __pageData,d as default};
